import sys

def solve(moves: str) -> int:
    x, y = 0, 0
    visited = {(x, y)}  # starting house

    for c in moves:
        if c == '^':
            y += 1
        elif c == 'v':
            y -= 1
        elif c == '>':
            x += 1
        elif c == '<':
            x -= 1
        else:
            continue  # ignore any unexpected characters
        visited.add((x, y))

    return len(visited)

def main():
    moves = sys.stdin.readline().strip()
    print(solve(moves))

if __name__ == "__main__":
    main()

