import sys

def is_nice_part2(s: str) -> bool:
    n = len(s)
    if n < 3:
        return False

    # Condition (B): a letter repeats with exactly one letter between (s[i] == s[i+2])
    has_gap_repeat = False
    for i in range(n - 2):
        if s[i] == s[i + 2]:
            has_gap_repeat = True
            break

    if not has_gap_repeat:
        return False

    # Condition (A): a pair of two letters appears at least twice without overlapping
    first_pos = {}  # pair -> earliest start index
    for i in range(n - 1):
        pair = s[i:i + 2]
        if pair not in first_pos:
            first_pos[pair] = i
        else:
            j = first_pos[pair]
            # Non-overlap: first pair occupies [j, j+1], second starts at i
            if i - j >= 2:
                return True

    return False

def main():
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]
    nice_count = 0
    for s in lines:
        if s == "":
            continue
        if is_nice_part2(s):
            nice_count += 1
    print(nice_count)

if __name__ == "__main__":
    main()

