import sys

def solve():
    lines = []
    for ln in sys.stdin.read().splitlines():
        ln = ln.strip()
        if not ln:
            continue
        if set(ln) <= {'.', '#'}:
            lines.append(ln)

    if not lines:
        return

    h = len(lines)
    w = len(lines[0])

    cur = [[lines[r][c] == '#' for c in range(w)] for r in range(h)]

    def force_corners(g):
        g[0][0] = True
        g[0][w - 1] = True
        g[h - 1][0] = True
        g[h - 1][w - 1] = True

    force_corners(cur)

    dr = (-1, -1, -1, 0, 0, 1, 1, 1)
    dc = (-1, 0, 1, -1, 1, -1, 0, 1)

    for _ in range(100):
        nxt = [[False] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                cnt = 0
                for k in range(8):
                    nr = r + dr[k]
                    nc = c + dc[k]
                    if 0 <= nr < h and 0 <= nc < w and cur[nr][nc]:
                        cnt += 1

                if cur[r][c]:
                    nxt[r][c] = (cnt == 2 or cnt == 3)
                else:
                    nxt[r][c] = (cnt == 3)

        force_corners(nxt)
        cur = nxt

    ans = sum(cur[r][c] for r in range(h) for c in range(w))
    print(ans)

if __name__ == "__main__":
    solve()

