import sys
import re
from collections import deque, defaultdict

def tokenize(s: str):
    # Tokenize chemical formula into element symbols: uppercase + optional lowercase*
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if not s[i].isupper():
            # Shouldn't happen for valid AoC inputs, but keep safe
            j = i
            while j < n and not s[j].isupper():
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        j = i + 1
        while j < n and s[j].islower():
            j += 1
        tokens.append(s[i:j])
        i = j
    return tokens

def find_all_occurrences(tokens, pattern):
    # Return list of start indices where pattern matches tokens[start:start+len(pattern)]
    if not pattern:
        return []
    m = len(pattern)
    if m > len(tokens):
        return []
    res = []
    # naive scan is fine for AoC sizes
    for i in range(len(tokens) - m + 1):
        if tokens[i:i+m] == pattern:
            res.append(i)
    return res

def apply_replacement(tokens, start, pat_len, repl):
    # Replace tokens[start:start+pat_len] with repl
    return tokens[:start] + repl + tokens[start+pat_len:]

def greedy_reduce(rev_rules, target_tokens, max_steps=10000):
    # rev_rules: list of (lhs_tokens, rhs_tokens) meaning replace lhs with rhs
    # We start from target and try to reach ['e'].
    current = target_tokens[:]
    steps = 0
    seen = set()
    e_tok = ['e']
    if current == e_tok:
        return 0

    # Precompute lengths for heuristic
    rule_info = []
    for lhs, rhs in rev_rules:
        rule_info.append((lhs, rhs, len(lhs), len(rhs)))

    while steps < max_steps:
        key = tuple(current)
        if key in seen:
            return None
        seen.add(key)

        best = None  # (improvement, tie2, start, lhs, rhs, new_tokens)
        cur_len = len(current)

        for lhs, rhs, l_len, r_len in rule_info:
            starts = find_all_occurrences(current, lhs)
            if not starts:
                continue
            improvement = l_len - r_len  # positive means length reduction
            for st in starts:
                new_tokens = apply_replacement(current, st, l_len, rhs)
                # Heuristic: maximize length reduction; then minimize resulting length; then lexicographic tie-break
                # (lexicographic on token strings for determinism)
                tie2 = (len(new_tokens), tuple(new_tokens))
                cand = (improvement, -tie2[0], tie2[1], st, lhs, rhs, new_tokens)
                if best is None or cand > best:
                    best = cand

        if best is None:
            return None

        new_tokens = best[-1]
        steps += 1
        current = new_tokens
        if current == e_tok:
            return steps

        # If we are not making progress (length not decreasing), greedy may loop; bail out.
        if len(current) >= cur_len and steps > 50:
            return None

    return None

def bidirectional_bfs(rules, rev_rules, target_tokens, max_total_states=200000):
    # Forward from e using original rules; backward from target using reverse rules.
    e_tokens = ['e']
    if target_tokens == e_tokens:
        return 0

    # Precompute rule lengths and indexing by lhs first token for faster matching
    f_rules = []
    for lhs, rhs in rules:
        f_rules.append((lhs, rhs, len(lhs), len(rhs)))
    b_rules = []
    for lhs, rhs in rev_rules:
        b_rules.append((lhs, rhs, len(lhs), len(rhs)))

    def neighbors_from(state_tokens, rule_list):
        # Generate neighbors by applying one rule at one position
        res = []
        for lhs, rhs, l_len, _ in rule_list:
            if l_len > len(state_tokens):
                continue
            starts = find_all_occurrences(state_tokens, lhs)
            for st in starts:
                res.append(apply_replacement(state_tokens, st, l_len, rhs))
        return res

    # Use sets of tuples for hashing
    start = tuple(e_tokens)
    goal = tuple(target_tokens)

    front_f = {start}
    front_b = {goal}
    dist_f = {start: 0}
    dist_b = {goal: 0}

    # Expand smaller frontier
    while front_f and front_b:
        if len(dist_f) + len(dist_b) > max_total_states:
            return None

        if len(front_f) <= len(front_b):
            next_front = set()
            for st in front_f:
                st_tokens = list(st)
                d = dist_f[st]
                for nb in neighbors_from(st_tokens, f_rules):
                    nb_t = tuple(nb)
                    if nb_t in dist_f:
                        continue
                    dist_f[nb_t] = d + 1
                    if nb_t in dist_b:
                        return dist_f[nb_t] + dist_b[nb_t]
                    next_front.add(nb_t)
            front_f = next_front
        else:
            next_front = set()
            for st in front_b:
                st_tokens = list(st)
                d = dist_b[st]
                for nb in neighbors_from(st_tokens, b_rules):
                    nb_t = tuple(nb)
                    if nb_t in dist_b:
                        continue
                    dist_b[nb_t] = d + 1
                    if nb_t in dist_f:
                        return dist_f[nb_t] + dist_b[nb_t]
                    next_front.add(nb_t)
            front_b = next_front

    return None

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines()]
    lines = [ln for ln in lines if ln != ""]
    if not lines:
        return

    rules = []
    target = None
    for ln in lines:
        if "=>" in ln:
            lhs, rhs = [x.strip() for x in ln.split("=>")]
            rules.append((tokenize(lhs), tokenize(rhs)))
        else:
            target = tokenize(ln.strip())

    if target is None:
        return

    # Part Two: minimum steps from e to target
    # Build reverse rules: for each A => B, create B => A
    rev_rules = [(rhs, lhs) for (lhs, rhs) in rules]

    # Greedy reduction first
    ans = greedy_reduce(rev_rules, target)
    if ans is not None:
        print(ans)
        return

    # Fallback: bidirectional BFS
    ans = bidirectional_bfs(rules, rev_rules, target)
    if ans is None:
        # As a last resort, try greedy with different max_steps
        ans = greedy_reduce(rev_rules, target, max_steps=50000)
    if ans is None:
        # If still none, print -1 (shouldn't happen for valid AoC inputs)
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    solve()

