import sys

def solve(target: int) -> int:
    # Each elf e delivers to houses e, 2e, ..., 50e (cap of 50 houses)
    # Each delivery adds 10*e presents.
    if target <= 10:
        return 1

    # Start with a heuristic upper bound and expand until we find an answer.
    N = max(1, (target // 10) * 2)

    while True:
        presents = [0] * (N + 1)

        # Sieve-like accumulation
        for e in range(1, N + 1):
            m_max = N // e
            if m_max > 50:
                m_max = 50
            if m_max <= 0:
                continue
            add = 10 * e
            # Add to houses: e*m for m in [1..m_max]
            for m in range(1, m_max + 1):
                presents[e * m] += add

        # Find the first house meeting the target
        for house in range(1, N + 1):
            if presents[house] >= target:
                return house

        # If not found, increase search space and retry
        N *= 2


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    target = int(data[0])
    print(solve(target))

if __name__ == "__main__":
    main()

