def parse_program(lines):
    program = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.replace(',', '').split()
        op = parts[0]
        if op in ("hlf", "tpl", "inc"):
            program.append((op, parts[1]))
        elif op in ("jmp",):
            program.append((op, int(parts[1])))
        elif op in ("jie", "jio"):
            program.append((op, parts[1], int(parts[2])))
        else:
            raise ValueError(f"Unknown opcode: {op}")
    return program

