    a = 0
    b = 0
    ip = 0
    n = len(program)

    while 0 <= ip < n:
        inst = program[ip]
        op = inst[0]

        if op == "hlf":
            r = inst[1]
            if r == "a":
                a //= 2
            else:
                b //= 2
            ip += 1
