import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    favorite = int(data)

    start = (1, 1)
    target = (31, 39)

    def is_open(x: int, y: int) -> bool:
        v = x*x + 3*x + 2*x*y + y + y*y + favorite
        return (v.bit_count() % 2) == 0  # even => open

    # If start is somehow a wall (shouldn't happen for valid inputs), no path exists.
    if not is_open(*start):
        print(-1)
        return

    q = deque([(start[0], start[1], 0)])
    visited = {start}

    while q:
        x, y, d = q.popleft()
        if (x, y) == target:
            print(d)
            return

        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if nx < 0 or ny < 0:
                continue
            if (nx, ny) in visited:
                continue
            if is_open(nx, ny):
                visited.add((nx, ny))
                q.append((nx, ny, d + 1))

    print(-1)

if __name__ == "__main__":
    solve()

