import sys
import hashlib

def solve(salt: str) -> int:
    salt = salt.strip()

    # Cache computed hashes to avoid recomputation
    hash_cache = {}

    def md5_hex(i: int) -> str:
        if i in hash_cache:
            return hash_cache[i]
        h = hashlib.md5((salt + str(i)).encode("utf-8")).hexdigest()
        hash_cache[i] = h
        return h

    def first_triplet_char(h: str):
        # Return the first character that appears 3 times in a row, else None
        for k in range(len(h) - 2):
            c = h[k]
            if c == h[k + 1] == h[k + 2]:
                return c
        return None

    def quintuplet_chars(h: str):
        # Return set of characters that appear 5 times in a row (anywhere)
        res = set()
        for k in range(len(h) - 4):
            c = h[k]
            if c == h[k + 1] == h[k + 2] == h[k + 3] == h[k + 4]:
                res.add(c)
        return res

    # Active candidates grouped by needed character for efficiency
    # Each bucket holds trigger indices that are still within their 1000 lookahead window.
    active = {ch: set() for ch in "0123456789abcdef"}

    keys_found = 0
    index = 0

    while True:
        # Expire candidates whose deadline < current index
        # Since we store only trigger indices, we need to know their deadlines.
        # We'll compute deadlines as trigger + 1000 and remove if expired.
        # To keep this efficient, we do expiration by scanning buckets and removing expired triggers.
        # Active set sizes are small in practice.
        for ch in active:
            expired = [t for t in active[ch] if t + 1000 < index]
            for t in expired:
                active[ch].remove(t)

        h = md5_hex(index)

        # Confirm candidates using any quintuplets in this hash
        qchars = quintuplet_chars(h)
        for ch in qchars:
            if active[ch]:
                # Confirm all candidates with this needed char
                # Order of confirmation doesn't matter for correctness of count,
                # but we must stop at the 64th key and return its trigger index.
                triggers = sorted(active[ch])
                for t in triggers:
                    keys_found += 1
                    if keys_found == 64:
                        return t
                active[ch].clear()

        # Add new candidate from first triplet in this hash
        trip = first_triplet_char(h)
        if trip is not None:
            active[trip].add(index)

        index += 1


def main():
    salt = sys.stdin.readline()
    print(solve(salt))

if __name__ == "__main__":
    main()

