import sys
import re
from collections import defaultdict

def parse_input(lines):
    weight = {}
    children = defaultdict(list)

    line_re = re.compile(r'^([a-zA-Z0-9_]+)\s+\((\-?\d+)\)(?:\s+->\s+(.*))?$')
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = line_re.match(line)
        if not m:
            continue
        name = m.group(1)
        w = int(m.group(2))
        weight[name] = w
        rhs = m.group(3)
        if rhs:
            children[name] = [c.strip() for c in rhs.split(',') if c.strip()]
        else:
            children[name] = []

    return weight, children

def find_root(weight, children):
    all_children = set()
    for p, ch in children.items():
        for c in ch:
            all_children.add(c)
    # root is the node that is never a child
    for node in weight.keys():
        if node not in all_children:
            return node
    # Fallback (shouldn't happen with valid input)
    return next(iter(weight.keys()))

def solve(weight, children):
    total_memo = {}

    def subtree_total(node):
        if node in total_memo:
            return total_memo[node]
        s = weight[node]
        for c in children[node]:
            s += subtree_total(c)
        total_memo[node] = s
        return s

    def find_correction(node):
        # If leaf, nothing to correct below
        if not children[node]:
            return None

        child_totals = [(c, subtree_total(c)) for c in children[node]]
        totals = [t for _, t in child_totals]

        # If already balanced, no correction needed here
        if len(set(totals)) == 1:
            return None

        # Determine majority (correct) and outlier (wrong)
        freq = defaultdict(int)
        for t in totals:
            freq[t] += 1

        # Majority total appears more times; outlier appears once
        target_total = None
        wrong_total = None
        for t, cnt in freq.items():
            if cnt > 1:
                target_total = t
            else:
                wrong_total = t

        # Identify the wrong child
        wrong_child = None
        for c, t in child_totals:
            if t == wrong_total:
                wrong_child = c
                break

        # Recurse deeper first
        deeper = find_correction(wrong_child)
        if deeper is not None:
            return deeper

