import sys

def solve(stream: str) -> int:
    in_garbage = False
    skip_next = False
    depth = 0
    total_score = 0

    for c in stream:
        if in_garbage:
            if skip_next:
                skip_next = False
                continue
            if c == '!':
                skip_next = True
            elif c == '>':
                in_garbage = False
            # else: ignore any other character inside garbage
        else:
            if c == '<':
                in_garbage = True
            elif c == '{':
                depth += 1
                total_score += depth
            elif c == '}':
                depth -= 1
            # else: ignore commas and any other characters outside garbage

    return total_score

def main():
    data = sys.stdin.read()
    stream = data.strip()
    print(solve(stream))

if __name__ == "__main__":
    main()

