import sys

def parse_pattern(s: str):
    return s.strip().split('/')

def key_of(pat):
    return '/'.join(pat)

def rotate90(pat):
    # Rotate pattern 90 degrees clockwise
    n = len(pat)
    return [''.join(pat[n - 1 - r][c] for r in range(n)) for c in range(n)]

def flip_horizontal(pat):
    # Mirror left-right
    return [row[::-1] for row in pat]

def all_variants(pat):
    # D4 symmetry group: 4 rotations of original + 4 rotations of flipped
    variants = set()
    p = pat
    for _ in range(4):
        variants.add(key_of(p))
        p = rotate90(p)
    p = flip_horizontal(pat)
    for _ in range(4):
        variants.add(key_of(p))
        p = rotate90(p)
    return variants

def enhance(grid, rules, iterations):
    for _ in range(iterations):
        n = len(grid)
        if n % 2 == 0:
            b, out_b = 2, 3
        else:
            b, out_b = 3, 4

        blocks = n // b
        new_n = blocks * out_b
        new_grid = [['.' for _ in range(new_n)] for _ in range(new_n)]

        for br in range(blocks):
            for bc in range(blocks):
                block = [grid[br * b + i][bc * b: bc * b + b] for i in range(b)]
                out_pat = rules[key_of(block)]  # list[str] length out_b

                for i in range(out_b):
                    row = out_pat[i]
                    for j in range(out_b):
                        new_grid[br * out_b + i][bc * out_b + j] = row[j]

        grid = [''.join(row) for row in new_grid]
    return grid

def solve():
    rules = {}

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        left, right = line.split(' => ')
        in_pat = parse_pattern(left)
        out_pat = parse_pattern(right)

        for k in all_variants(in_pat):
            rules[k] = out_pat

    grid = parse_pattern(".#./..#/###")
    final_grid = enhance(grid, rules, 5)
    return sum(row.count('#') for row in final_grid)

if __name__ == "__main__":
    print(solve())

