import sys
from functools import lru_cache

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines() if line.strip()]
    comps = []
    by_type = {}

    for i, line in enumerate(lines):
        a_str, b_str = line.split('/')
        a, b = int(a_str), int(b_str)
        comps.append((a, b))
        by_type.setdefault(a, []).append(i)
        by_type.setdefault(b, []).append(i)

    n = len(comps)
    if n == 0:
        return 0

    # If n is small enough, use a bitmask for used components.
    # For larger n, bitmask memoization may be infeasible; however, typical AoC inputs fit.
    if n > 60:
        # Fallback: no memoization (still correct, may be slow).
        sys.setrecursionlimit(1000000)

        best_global = 0

        def dfs(current_type, used_mask):
            nonlocal best_global
            best = 0
            for idx in by_type.get(current_type, []):
                if (used_mask >> idx) & 1:
                    continue
                a, b = comps[idx]
                next_type = b if a == current_type else a
                cand = (a + b) + dfs(next_type, used_mask | (1 << idx))
                if cand > best:
                    best = cand
            return best

        return dfs(0, 0)

    sys.setrecursionlimit(1000000)

    @lru_cache(maxsize=None)
    def dfs(current_type: int, used_mask: int) -> int:
        best = 0
        for idx in by_type.get(current_type, []):
            if (used_mask >> idx) & 1:
                continue
            a, b = comps[idx]
            next_type = b if a == current_type else a
            cand = (a + b) + dfs(next_type, used_mask | (1 << idx))
            if cand > best:
                best = cand
        return best

    return dfs(0, 0)

def main():
    data = sys.stdin.read()
    ans = solve(data)
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
