import sys
import re

def solve(data: str) -> str:
    lines = [ln.strip() for ln in data.strip().splitlines() if ln.strip()]
    if not lines:
        return ""

    claims = []
    max_x2 = 0
    max_y2 = 0

    pat = re.compile(r"#(\d+)\s*@\s*(\d+),(\d+):\s*(\d+)x(\d+)")
    for ln in lines:
        m = pat.match(ln)
        if not m:
            continue
        cid = int(m.group(1))
        left = int(m.group(2))
        top = int(m.group(3))
        w = int(m.group(4))
        h = int(m.group(5))
        x1, x2 = left, left + w
        y1, y2 = top, top + h
        claims.append((cid, x1, x2, y1, y2))
        if x2 > max_x2:
            max_x2 = x2
        if y2 > max_y2:
            max_y2 = y2

    # 2D difference array (Imos method) on unit grid cells
    # cover[x][y] will represent how many claims cover the unit square at (x, y)
    diff = [[0] * (max_y2 + 2) for _ in range(max_x2 + 2)]

    for _, x1, x2, y1, y2 in claims:
        diff[x1][y1] += 1
        diff[x2][y1] -= 1
        diff[x1][y2] -= 1
        diff[x2][y2] += 1

    # Prefix sums to recover coverage counts
    cover = [[0] * (max_y2) for _ in range(max_x2)]
    for x in range(max_x2):
        row_sum = 0
        for y in range(max_y2):
            row_sum += diff[x][y]
            if x == 0:
                cover[x][y] = row_sum
            else:
                cover[x][y] = cover[x - 1][y] + row_sum

    # Part 1: count squares covered by 2+ claims (computed per plan)
    overlap_count = 0
    for x in range(max_x2):
        for y in range(max_y2):
            if cover[x][y] >= 2:
                overlap_count += 1

    # Part 2: find the only claim that doesn't overlap any other claim
    intact = {cid: True for cid, _, _, _, _ in claims}

    for cid, x1, x2, y1, y2 in claims:
        ok = True
        for x in range(x1, x2):
            for y in range(y1, y2):
                if cover[x][y] >= 2:
                    ok = False
                    break
            if not ok:
                break
        intact[cid] = ok

    # Guaranteed exactly one intact claim
    for cid, _, _, _, _ in claims:
        if intact.get(cid, False):
