import sys
from collections import deque

def solve(regex: str) -> int:
    s = regex.strip()
    if s and s[0] == '^':
        s = s[1:]
    if s and s[-1] == '$':
        s = s[:-1]

    # Adjacency list for rooms (undirected graph)
    adj = {}
    def add_edge(a, b):
        if a not in adj:
            adj[a] = set()
        if b not in adj:
            adj[b] = set()
        adj[a].add(b)
        adj[b].add(a)

    start = (0, 0)
    adj[start] = set()

    current_positions = {start}
    stack = []  # frames: (entry_positions, accumulated_positions)

    for c in s:
        if c in "NSEW":
            next_positions = set()
            for (x, y) in current_positions:
                if c == 'N':
                    nx, ny = x, y - 1
                elif c == 'S':
                    nx, ny = x, y + 1
                elif c == 'W':
                    nx, ny = x - 1, y
                else:  # 'E'
                    nx, ny = x + 1, y
                nxt = (nx, ny)
                add_edge((x, y), nxt)
                next_positions.add(nxt)
            current_positions = next_positions

        elif c == '(':
            # Start a new group: alternatives begin from the same entry positions
            stack.append([set(current_positions), set()])

        elif c == '|':
            # End current alternative; merge into accumulated and reset to entry
            frame = stack[-1]
            frame[1].update(current_positions)
            current_positions = set(frame[0])

        elif c == ')':
            # End group; merge last alternative and pop
            frame = stack.pop()
            frame[1].update(current_positions)
            current_positions = frame[1]

        else:
            # Should not happen for valid inputs
            pass

    # BFS for shortest number of doors to each room
    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj.get(u, ()):
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)

    return max(dist.values()) if dist else 0

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    print(solve(data))

if __name__ == "__main__":
    main()

