import sys
import math

def parse_program(lines):
    ip_reg = None
    prog = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith("#ip"):
            ip_reg = int(line.split()[1])
            continue
        parts = line.split()
        op = parts[0]
        a, b, c = map(int, parts[1:])
        prog.append((op, a, b, c))
    if ip_reg is None:
        raise ValueError("Missing #ip declaration")
    return ip_reg, prog

def run_interpreter(ip_reg, prog, init_r0=0, step_cap=50_000_000, stop_on_repeat=False):
    # Registers 0..5
    r = [0, 0, 0, 0, 0, 0]
    r[0] = init_r0

    ip = 0
    steps = 0

    # Optional: detect repeated (ip, registers) states (rarely needed)
    seen = set()

    while 0 <= ip < len(prog):
        if steps >= step_cap:
            return r, ip, steps, False

        if stop_on_repeat:
            key = (ip, tuple(r))
            if key in seen:
                return r, ip, steps, True
            seen.add(key)

        r[ip_reg] = ip
        op, a, b, c = prog[ip]

        # Execute
        if op == "addr":
            r[c] = r[a] + r[b]
        elif op == "addi":
            r[c] = r[a] + b
        elif op == "mulr":
            r[c] = r[a] * r[b]
        elif op == "muli":
            r[c] = r[a] * b
        elif op == "banr":
            r[c] = r[a] & r[b]
        elif op == "bani":
            r[c] = r[a] & b
        elif op == "borr":
            r[c] = r[a] | r[b]
        elif op == "bori":
            r[c] = r[a] | b
        elif op == "setr":
            r[c] = r[a]
        elif op == "seti":
            r[c] = a
        elif op == "gtir":
            r[c] = 1 if a > r[b] else 0
        elif op == "gtri":
            r[c] = 1 if r[a] > b else 0
        elif op == "gtrr":
            r[c] = 1 if r[a] > r[b] else 0
        elif op == "eqir":
            r[c] = 1 if a == r[b] else 0
        elif op == "eqri":
            r[c] = 1 if r[a] == b else 0
        elif op == "eqrr":
            r[c] = 1 if r[a] == r[b] else 0
        else:
            raise ValueError(f"Unknown opcode: {op}")

        ip = r[ip_reg]
        ip += 1
        steps += 1

    return r, ip, steps, False

def divisor_sum(n):
    if n <= 0:
        return 0
    s = 0
    r = int(math.isqrt(n))
    for d in range(1, r + 1):
        if n % d == 0:
            s += d
            q = n // d
            if q != d:
                s += q
    return s

def solve():
    lines = sys.stdin.read().splitlines()
    ip_reg, prog = parse_program(lines)

    # Day 19 typically reduces to sum of divisors of a constructed n.
    # We'll derive n by running the interpreter until we reach the hot loop region,
    # then reading the register that holds n.
    #
    # Heuristic: find the first time we see the instruction pointer value that
    # corresponds to the start of the divisor-summing loop. In the canonical AoC
    # input, this is stable and occurs after a small prelude.
    #
    # We'll run with a step cap and record when ip repeats with same registers
    # pattern; then infer n from the register values at that time.
    #
    # To keep it robust, we instead use a direct approach:
    # - Run interpreter for both init_r0=0 and init_r0=1 but stop once we detect
    #   that the program is in the divisor loop by observing that one register
    #   becomes a fixed "n" and another register is used as a loop counter.
    #
    # We'll detect "n" as the value that remains constant for many steps while
    # other registers change. We'll do this by sampling register tuples.
    def infer_n(init_r0):
        # Sample for a while; look for a stable value in some register.
        r = [0, 0, 0, 0, 0, 0]
        r[0] = init_r0
        ip = 0
        steps = 0
        step_cap = 5_000_000

        # Track candidate stable values per register
        # We'll store last seen value and count of consecutive matches.
        last = [None] * 6
        consec = [0] * 6

        # Also track when we are likely in the hot loop: many consecutive matches
        # for some register while ip stays within a range.
        while 0 <= ip < len(prog) and steps < step_cap:
            r[ip_reg] = ip
            op, a, b, c = prog[ip]

            # Execute
            if op == "addr":
                r[c] = r[a] + r[b]
            elif op == "addi":
                r[c] = r[a] + b
            elif op == "mulr":
                r[c] = r[a] * r[b]
            elif op == "muli":
                r[c] = r[a] * b
            elif op == "banr":
                r[c] = r[a] & r[b]
            elif op == "bani":
                r[c] = r[a] & b
            elif op == "borr":
                r[c] = r[a] | r[b]
            elif op == "bori":
                r[c] = r[a] | b
            elif op == "setr":
                r[c] = r[a]
            elif op == "seti":
                r[c] = a
            elif op == "gtir":
                r[c] = 1 if a > r[b] else 0
            elif op == "gtri":
                r[c] = 1 if r[a] > b else 0
            elif op == "gtrr":
                r[c] = 1 if r[a] > r[b] else 0
            elif op == "eqir":
                r[c] = 1 if a == r[b] else 0
            elif op == "eqri":
                r[c] = 1 if r[a] == b else 0
            elif op == "eqrr":
                r[c] = 1 if r[a] == r[b] else 0
            else:
                raise ValueError(f"Unknown opcode: {op}")

            ip = r[ip_reg] + 1
            steps += 1

            # Update stability counters
            for i in range(6):
                if last[i] is None:
                    last[i] = r[i]
                    consec[i] = 1
                else:
                    if r[i] == last[i]:
                        consec[i] += 1
                    else:
                        last[i] = r[i]
                        consec[i] = 1

            # Heuristic threshold: one register stable for a lot of steps
            # while we haven't halted.
            if steps > 200_000:
                # pick best stable register
                best_i = max(range(6), key=lambda i: consec[i])
                if consec[best_i] > 200_000:
                    return r[best_i]

        # Fallback: run longer and just return the most stable register at end
        best_i = max(range(6), key=lambda i: consec[i])
        return r[best_i]

    n1 = infer_n(0)
    n2 = infer_n(1)

    ans1 = divisor_sum(n1)
    ans2 = divisor_sum(n2)

    # Output: two lines (common AoC format)
    sys.stdout.write(f"{ans1}\n{ans2}\n")

if __name__ == "__main__":
    solve()

