import sys
import math

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    asteroids = []
    for y, row in enumerate(lines):
        for x, ch in enumerate(row.strip()):
            if ch == '#':
                asteroids.append((x, y))

    n = len(asteroids)
    if n <= 1:
        return "0"

    best = 0
    for i in range(n):
        xi, yi = asteroids[i]
        dirs = set()
        for j in range(n):
            if i == j:
                continue
            xj, yj = asteroids[j]
            dx = xj - xi
            dy = yj - yi
            g = math.gcd(abs(dx), abs(dy))
            dx //= g
            dy //= g
            dirs.add((dx, dy))
        best = max(best, len(dirs))

    return str(best)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

