import re

def parse_input(data: str):
    nums = re.compile(r"-?\d+")
    moons = []
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        found = nums.findall(line)
        if len(found) != 3:
            raise ValueError(f"Bad input line: {line}")
        x, y, z = map(int, found)
        moons.append([x, y, z])
    return moons

def energy_after_steps(moons, steps=1000):
    n = len(moons)
    pos = [m[:] for m in moons]
    vel = [[0, 0, 0] for _ in range(n)]

    for _ in range(steps):
        # Apply gravity (pairwise, axis-separable)
        for i in range(n - 1):
            for j in range(i + 1, n):
                for a in range(3):
                    if pos[i][a] < pos[j][a]:
                        vel[i][a] += 1
                        vel[j][a] -= 1
                    elif pos[i][a] > pos[j][a]:
                        vel[i][a] -= 1
                        vel[j][a] += 1

        # Apply velocity
        for i in range(n):
            pos[i][0] += vel[i][0]
            pos[i][1] += vel[i][1]
            pos[i][2] += vel[i][2]

    total = 0
    for i in range(n):
        pot = abs(pos[i][0]) + abs(pos[i][1]) + abs(pos[i][2])
        kin = abs(vel[i][0]) + abs(vel[i][1]) + abs(vel[i][2])
        total += pot * kin
    return total

def main():
    data = sys.stdin.read()
    moons = parse_input(data)
    print(energy_after_steps(moons, 1000))

if __name__ == "__main__":
    main()

