import sys

REQUIRED_FIELDS = {"byr", "iyr", "eyr", "hgt", "hcl", "ecl", "pid"}
EYE_COLORS = {"amb", "blu", "brn", "gry", "grn", "hzl", "oth"}


def is_year_valid(s: str, lo: int, hi: int) -> bool:
    if len(s) != 4 or not s.isdigit():
        return False
    v = int(s)
    return lo <= v <= hi


def is_hgt_valid(s: str) -> bool:
    if s.endswith("cm"):
        num = s[:-2]
        if not num.isdigit():
            return False
        v = int(num)
        return 150 <= v <= 193
    if s.endswith("in"):
        num = s[:-2]
        if not num.isdigit():
            return False
        v = int(num)
        return 59 <= v <= 76
    return False


def is_hcl_valid(s: str) -> bool:
    if len(s) != 7 or s[0] != "#":
        return False
    hex_part = s[1:]
    for ch in hex_part:
        if not (("0" <= ch <= "9") or ("a" <= ch <= "f")):
            return False
    return True


def is_ecl_valid(s: str) -> bool:
    return s in EYE_COLORS


def is_pid_valid(s: str) -> bool:
    return len(s) == 9 and s.isdigit()


def passport_valid(fields: dict) -> bool:
    # Presence check (cid optional)
    for k in REQUIRED_FIELDS:
        if k not in fields:
            return False

    # Strict value validation
    if not is_year_valid(fields["byr"], 1920, 2002):
        return False
    if not is_year_valid(fields["iyr"], 2010, 2020):
        return False
    if not is_year_valid(fields["eyr"], 2020, 2030):
        return False
    if not is_hgt_valid(fields["hgt"]):
        return False
    if not is_hcl_valid(fields["hcl"]):
        return False
    if not is_ecl_valid(fields["ecl"]):
        return False
    if not is_pid_valid(fields["pid"]):
        return False

    return True


def solve(text: str) -> int:
    # Split into passport blocks by blank lines
    blocks = text.strip().split("\n\n") if text.strip() else []
    valid_count = 0

    for block in blocks:
        fields = {}
        for token in block.split():
            if ":" in token:
                k, v = token.split(":", 1)
                fields[k] = v
        if passport_valid(fields):
            valid_count += 1

    return valid_count


def main():
    data = sys.stdin.read()
    print(solve(data))


if __name__ == "__main__":
    main()

