import sys

def tokenize(line: str):
    tokens = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c == ' ':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and line[j].isdigit():
                j += 1
            tokens.append(int(line[i:j]))
            i = j
        elif c in '+*()':
            tokens.append(c)
            i += 1
        else:
            # Input is assumed valid per problem statement
            i += 1
    return tokens

def evaluate(expr_tokens, prec):
    values = []
    ops = []

    def apply_op():
        op = ops.pop()
        b = values.pop()
        a = values.pop()
        if op == '+':
            values.append(a + b)
        else:  # op == '*'
            values.append(a * b)

    for tok in expr_tokens:
        if isinstance(tok, int):
            values.append(tok)
        elif tok == '(':
            ops.append(tok)
        elif tok == ')':
            while ops and ops[-1] != '(':
                apply_op()
            # Discard '('
            if ops and ops[-1] == '(':
                ops.pop()
        else:  # operator '+' or '*'
            while ops and ops[-1] != '(' and prec(ops[-1]) >= prec(tok):
                apply_op()
            ops.append(tok)

    while ops:
        apply_op()

    return values[-1] if values else 0

def main():
    lines = [ln.strip() for ln in sys.stdin.read().splitlines()]
    lines = [ln for ln in lines if ln]

    # Part Two: addition evaluated before multiplication
    def prec(op: str) -> int:
        return 2 if op == '+' else 1

    total = 0
    for line in lines:
        tokens = tokenize(line)
        total += evaluate(tokens, prec)

    print(total)

if __name__ == "__main__":
    main()

