import sys
from collections import deque

def parse_decks(lines):
    deck1, deck2 = deque(), deque()
    current = None

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line == "Player 1:":
            current = deck1
            continue
        if line == "Player 2:":
            current = deck2
            continue
        if current is not None:
            current.append(int(line))

    return deck1, deck2

def play_combat(deck1, deck2):
    # Part 1 rules: no recursion, no repeated-state detection
    while deck1 and deck2:
        c1 = deck1.popleft()
        c2 = deck2.popleft()
        if c1 > c2:
            deck1.append(c1)
            deck1.append(c2)
        else:
            deck2.append(c2)
            deck2.append(c1)
    return deck1 if deck1 else deck2

def score_deck(deck):
    # Bottom card multiplier is 1, top card multiplier is len(deck)
    n = len(deck)
    score = 0
    for i, v in enumerate(deck):
        multiplier = n - i
        score += v * multiplier
    return score

def main():
    lines = sys.stdin.read().splitlines()
    deck1, deck2 = parse_decks(lines)
    winning_deck = play_combat(deck1, deck2)
    print(score_deck(winning_deck))

if __name__ == "__main__":
    main()

