    for row in grid:
        if len(row) != c:
            raise ValueError("Invalid input: inconsistent row lengths")

    risk_sum = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    for i in range(r):
