            h = grid[i][j]
            is_low = True
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < r and 0 <= nj < c:
                    if grid[ni][nj] <= h:
                        is_low = False
                        break
            if is_low:
                risk_sum += 1 + h

    print(risk_sum)

