import sys
from collections import defaultdict

def count_paths_part1(lines):
    graph = defaultdict(list)
    for line in lines:
        line = line.strip()
        if not line:
            continue
        a, b = line.split('-')
        graph[a].append(b)
        graph[b].append(a)

    def is_small(cave: str) -> bool:
        return cave.islower()

    visited_small = set()

    sys.setrecursionlimit(1000000)

    def dfs(cur: str) -> int:
        if cur == "end":
            return 1

        total = 0
        for nxt in graph[cur]:
            if nxt == "start":
                continue
            if is_small(nxt):
                if nxt in visited_small:
                    continue
                visited_small.add(nxt)
                total += dfs(nxt)
                visited_small.remove(nxt)
            else:
                total += dfs(nxt)
        return total

    return dfs("start")

def main():
    lines = sys.stdin.read().splitlines()
    ans = count_paths_part1(lines)
    print(ans)

if __name__ == "__main__":
    main()

