import sys
from functools import lru_cache

def solve(data: str) -> str:
    edges = [line.strip() for line in data.splitlines() if line.strip()]
    adj = {}
    for line in edges:
        a, b = line.split("-")
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)

    # Identify small caves and index them for compact state encoding
    small = [name for name in adj.keys() if name.islower()]
    # Ensure start/end are treated as small but we will never allow revisiting start
    # and end terminates immediately.
    small_set = set(small)
    small_indices = {name: i for i, name in enumerate(small)}

    # Precompute cave types
    is_big = {name: (name.isupper()) for name in adj.keys()}

    # Base-3 encoding for visit counts of small caves:
    # 0 = unvisited, 1 = visited once, 2 = visited twice
    # We'll store counts for all small caves; start/end are included but start is never revisited,
    # and end ends the path immediately.
    n_small = len(small_indices)
    pow3 = [1] * (n_small + 1)
    for i in range(n_small):
        pow3[i + 1] = pow3[i] * 3

    def get_count(code: int, idx: int) -> int:
        return (code // pow3[idx]) % 3

    def set_count(code: int, idx: int, new_val: int) -> int:
        cur = get_count(code, idx)
        if cur == new_val:
            return code
        return code + (new_val - cur) * pow3[idx]

    # Map node names to stable integer ids for memoization
    node_ids = {name: i for i, name in enumerate(adj.keys())}
    id_to_node = {i: name for name, i in node_ids.items()}

    start_id = node_ids["start"]
    end_id = node_ids["end"]

    @lru_cache(maxsize=None)
    def dfs(cur_id: int, used_double: int, code: int) -> int:
        if cur_id == end_id:
            return 1

        cur = id_to_node[cur_id]
        total = 0

        for nxt in adj[cur]:
            if nxt == "start":
                continue
            nxt_id = node_ids[nxt]

            if is_big[nxt]:
                total += dfs(nxt_id, used_double, code)
            else:
                idx = small_indices[nxt]
                cnt = get_count(code, idx)
                if cnt == 0:
                    new_code = set_count(code, idx, 1)
                    total += dfs(nxt_id, used_double, new_code)
                elif cnt == 1:
                    if used_double == 0:
                        new_code = set_count(code, idx, 2)
                        total += dfs(nxt_id, 1, new_code)
                # cnt == 2 => cannot visit again

        return total

    # Initial state: no small caves visited yet
    initial_code = 0
    ans = dfs(start_id, 0, initial_code)
    return str(ans)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data) + "\n")

