import sys
from typing import List, Tuple, Union, Optional

Instr = Tuple[str, str, Union[str, int]]

def parse_program(lines: List[str]) -> List[Instr]:
    prog: List[Instr] = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        a = parts[1]
        if op == "inp":
            prog.append((op, a, 0))
        else:
            b_raw = parts[2]
            try:
                b = int(b_raw)
            except ValueError:
                b = b_raw
            prog.append((op, a, b))
    return prog

def split_into_blocks(prog: List[Instr]) -> List[List[Instr]]:
    blocks: List[List[Instr]] = []
    cur: List[Instr] = []
    for ins in prog:
        if ins[0] == "inp":
            if cur:
                blocks.append(cur)
            cur = [ins]
        else:
            cur.append(ins)
    if cur:
        blocks.append(cur)
    return blocks

def extract_params(block: List[Instr]) -> Tuple[int, int, int]:
    """
    Extract:
      divZ: constant in 'div z <divZ>'
      addX: constant in 'add x <addX>' (the one after x is computed from z)
      addY: constant in 'add y <addY>' (near the end)
    """
    divZ = None
    addX = None
    addY = None

    # Heuristic based on known MONAD template:
    # - div z <k> appears once per block
    # - add x <k> appears once per block (the one after 'mod x 26' and 'div z ...' in typical structure)
    # - add y <k> appears once per block (the one before 'mul y x' and 'add z y')
    for op, a, b in block:
        if op == "div" and a == "z" and isinstance(b, int):
            divZ = b
        elif op == "add" and a == "x" and isinstance(b, int):
            # In the template, this add x is the one used in x == w comparison.
            addX = b
        elif op == "add" and a == "y" and isinstance(b, int):
            addY = b

    if divZ is None or addX is None or addY is None:
        raise ValueError("Failed to extract parameters from block.")
    return divZ, addX, addY

def build_constraints(blocks: List[List[Instr]]) -> List[Tuple[int, int, int]]:
    """
    Returns list of constraints (j, i, delta) meaning:
      d_i = d_j + delta
    where j is from a push block (divZ==1) and i from a pop block (divZ==26).
    """
    stack: List[Tuple[int, int]] = []  # (index, addY) for divZ==1 blocks
    constraints: List[Tuple[int, int, int]] = []

    for i, block in enumerate(blocks):
        divZ, addX, addY = extract_params(block)
        if divZ == 1:
            stack.append((i, addY))
        elif divZ == 26:
            if not stack:
                raise ValueError("Pop block with empty stack.")
            j, addY_j = stack.pop()
            # Derived relation for this MONAD template:
            # d_i = d_j + (addY_j + addX_i)
            delta = addY_j + addX
            constraints.append((j, i, delta))
        else:
            raise ValueError(f"Unexpected divZ value: {divZ}")
    if stack:
        raise ValueError("Unmatched push blocks remain.")
    return constraints

def solve_greedy(constraints: List[Tuple[int, int, int]], maximize: bool) -> str:
    n = 14
    d: List[Optional[int]] = [None] * n
    # Map each index to its paired constraint (at most one in this template)
    pair: List[Optional[Tuple[int, int]]] = [None] * n  # for i: (other, delta) where d_i = d_other + delta? not used directly

    # We'll just use constraints list and assign consistently.
    # For each constraint (j,i,delta): d[i] = d[j] + delta
    # We'll process constraints in order of i (left-to-right) for greedy assignment.
    constraints_sorted = sorted(constraints, key=lambda t: t[1])

    def set_pair(j: int, i: int, delta: int, val_i: int):
        # set d[i]=val_i, d[j]=val_i - delta
        val_j = val_i - delta
        if not (1 <= val_j <= 9 and 1 <= val_i <= 9):
            return False
        if d[i] is not None and d[i] != val_i:
            return False
        if d[j] is not None and d[j] != val_j:
            return False
        d[i] = val_i
        d[j] = val_j
        return True

    def set_pair_from_j(j: int, i: int, delta: int, val_j: int):
        val_i = val_j + delta
        if not (1 <= val_j <= 9 and 1 <= val_i <= 9):
            return False
        if d[j] is not None and d[j] != val_j:
            return False
        if d[i] is not None and d[i] != val_i:
            return False
        d[j] = val_j
        d[i] = val_i
        return True

    # Greedy assignment from most significant to least:
    # At each position k, if unset, try to assign it to max/min consistent with any constraint involving it.
    # Since each index participates in at most one constraint, we can derive the needed counterpart if constraint exists.
    # Build lookup for constraints by index.
    by_index: List[List[Tuple[int, int, int]]] = [[] for _ in range(n)]
    for j, i, delta in constraints:
        by_index[j].append((j, i, delta))
        by_index[i].append((j, i, delta))

    for k in range(n):
        if d[k] is not None:
            continue
        # Determine if k is part of a constraint; if not, choose extreme digit.
        if not by_index[k]:
            d[k] = 9 if maximize else 1
            continue

        # In this template, k should be in exactly one constraint.
        # But handle multiple just in case by intersecting feasibility.
        feasible_vals = range(9, 0, -1) if maximize else range(1, 10)
        chosen = None
        for val in feasible_vals:
            ok = True
            # Check all constraints involving k
            for j, i, delta in by_index[k]:
                if k == i:
                    # d[i] = d[j] + delta => d[j] = d[i] - delta
                    val_j = val - delta
                    if not (1 <= val_j <= 9):
                        ok = False
                        break
                    if d[j] is not None and d[j] != val_j:
                        ok = False
                        break
                else:
                    # k == j
                    val_i = val + delta
                    if not (1 <= val_i <= 9):
                        ok = False
                        break
                    if d[i] is not None and d[i] != val_i:
                        ok = False
                        break
            if ok:
                chosen = val
                break
        if chosen is None:
            raise ValueError("No feasible digit assignment found.")
        # Apply chosen and propagate counterpart(s)
        d[k] = chosen
        for j, i, delta in by_index[k]:
            if k == i:
                val_j = chosen - delta
                if d[j] is None:
                    d[j] = val_j
            else:
                val_i = chosen + delta
                if d[i] is None:
                    d[i] = val_i

    if any(v is None for v in d):
        raise ValueError("Some digits remain unset.")
    return "".join(str(v) for v in d)  # type: ignore

def alu_run(prog: List[Instr], model: str) -> int:
    regs = {"w": 0, "x": 0, "y": 0, "z": 0}
    inp_idx = 0
    digits = [int(c) for c in model.strip()]
    for op, a, b in prog:
        if op == "inp":
            regs[a] = digits[inp_idx]
            inp_idx += 1
        else:
            aval = regs[a]
            if isinstance(b, int):
                bval = b
            else:
                bval = regs[b]
            if op == "add":
                regs[a] = aval + bval
            elif op == "mul":
                regs[a] = aval * bval
            elif op == "div":
                # truncate toward zero
                if bval == 0:
                    raise ZeroDivisionError("div by zero")
                regs[a] = int(aval / bval)
            elif op == "mod":
                if aval < 0 or bval <= 0:
                    raise ValueError("invalid mod operands")
                regs[a] = aval % bval
            elif op == "eql":
                regs[a] = 1 if aval == bval else 0
            else:
                raise ValueError(f"Unknown op {op}")
    return regs["z"]

def main():
    lines = sys.stdin.read().strip().splitlines()
    prog = parse_program(lines)
    blocks = split_into_blocks(prog)
    if len(blocks) != 14:
        raise ValueError(f"Expected 14 blocks, got {len(blocks)}")

    constraints = build_constraints(blocks)

    max_model = solve_greedy(constraints, maximize=True)
    if alu_run(prog, max_model) != 0:
        raise ValueError("Max model failed verification (z != 0).")

    min_model = solve_greedy(constraints, maximize=False)
    if alu_run(prog, min_model) != 0:
        raise ValueError("Min model failed verification (z != 0).")

    sys.stdout.write(max_model + "\n" + min_model + "\n")

if __name__ == "__main__":
    main()

