import sys
import re
from collections import deque

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if not lines:
        return

    flow = {}
    adj = {}

    pat = re.compile(r"Valve (\w+) has flow rate=(\d+); tunnels? leads? to valves? (.+)")
    for line in lines:
        m = pat.match(line)
        if not m:
            continue
        name = m.group(1)
        rate = int(m.group(2))
        neigh = [x.strip() for x in m.group(3).split(",")]
        flow[name] = rate
        adj[name] = neigh

    start = "AA"
    useful = [v for v, r in flow.items() if r > 0]
    n = len(useful)

    # Map useful valves to indices
    idx = {v: i for i, v in enumerate(useful)}
    rates = [flow[v] for v in useful]

    # Precompute shortest distances between relevant nodes (AA + useful)
    relevant = [start] + useful
    rel_count = n + 1

    dist = [[10**9] * rel_count for _ in range(rel_count)]

    def bfs(src):
        q = deque([src])
        d = {src: 0}
        while q:
            u = q.popleft()
            for w in adj.get(u, []):
                if w not in d:
                    d[w] = d[u] + 1
                    q.append(w)
        return d

    all_d = {}
    for r in relevant:
        all_d[r] = bfs(r)

    for i, a in enumerate(relevant):
        for j, b in enumerate(relevant):
            if b in all_d[a]:
                dist[i][j] = all_d[a][b]
            else:
                dist[i][j] = 10**9

    # Memoized recursion: state (posIndex, mask, time_left)
    # posIndex: 0..n where 0 corresponds to AA, and 1..n correspond to useful valves in order
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(posIndex, mask, time_left):
        best = 0
        # Try opening any unopened useful valve k
        for k in range(n):
            if (mask >> k) & 1:
                continue
            # distance from current position to useful valve k
            # current useful index in dist matrix:
            # posIndex==0 => AA, posIndex>0 => useful[posIndex-1]
            cur_rel = posIndex
            target_rel = k + 1
            d = dist[cur_rel][target_rel]
            if d >= 10**8:
                continue
            cost = d + 1  # move + open
            if cost > time_left:
                continue
            remaining = time_left - cost
            gain = rates[k] * remaining
            cand = gain + dfs(target_rel, mask | (1 << k), remaining)
            if cand > best:
                best = cand
        return best

    ans = dfs(0, 0, 30)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

