import sys
import re

def solve(inp: str) -> int:
    lines = inp.splitlines()

    # Split map and path by first blank line
    split_idx = None
    for i, line in enumerate(lines):
        if line.strip() == "":
            split_idx = i
            break
    if split_idx is None:
        # Fallback: find the line that looks like the instruction string
        for i, line in enumerate(lines):
            if re.fullmatch(r"[0-9LR]+", line.strip()):
                split_idx = i
                break
    if split_idx is None:
        raise ValueError("Could not find instruction line")

    map_lines = lines[:split_idx]
    instr_line = ""
    for j in range(split_idx, len(lines)):
        if lines[j].strip() != "":
            instr_line = lines[j].strip()
            break
    if not instr_line:
        raise ValueError("Missing instruction string")

    R = len(map_lines)
    C = max((len(s) for s in map_lines), default=0)
    BLANK = ' '

    grid = [[BLANK] * C for _ in range(R)]
    for r, s in enumerate(map_lines):
        for c, ch in enumerate(s):
            grid[r][c] = ch

    # Parse instructions into tokens: numbers and L/R
    tokens = []
    i = 0
    while i < len(instr_line):
        ch = instr_line[i]
        if ch.isdigit():
            j = i
            while j < len(instr_line) and instr_line[j].isdigit():
                j += 1
            tokens.append(int(instr_line[i:j]))
            i = j
        else:
            tokens.append(ch)  # 'L' or 'R'
            i += 1

    # Directions: 0=Right,1=Down,2=Left,3=Up
    dr = [0, 1, 0, -1]
    dc = [1, 0, -1, 0]

    # Precompute wrap transitions for each row/col segment
    # next_pos[r][c][dir] -> (nr, nc)
    next_r = [[[0] * 4 for _ in range(C)] for __ in range(R)]
    next_c = [[[0] * 4 for _ in range(C)] for __ in range(R)]

    # Initialize transitions for BLANK cells (unused)
    for r in range(R):
        for c in range(C):
            for d in range(4):
