import sys
from collections import deque

def solve(data: str) -> None:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    if not lines:
        return

    grid = [list(line) for line in lines]
    R, C = len(grid), len(grid[0])

    sr = sc = -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                sr, sc = r, c
                break
        if sr != -1:
            break

    # Directions: N, E, S, W
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    dir_names = ['N', 'E', 'S', 'W']
    opposite = {0: 2, 1: 3, 2: 0, 3: 1}  # index-based opposite

    # Pipe connectivity (ports)
    ports = {
        '|': {0, 2},  # N, S
        '-': {1, 3},  # E, W
        'L': {0, 1},  # N, E
        'J': {0, 3},  # N, W
        '7': {2, 3},  # S, W
        'F': {2, 1},  # S, E
        '.': set(),
    }

    # Infer which two directions S connects to
    start_ports = []
    for d, (dr, dc) in enumerate(dirs):
        nr, nc = sr + dr, sc + dc
        if not (0 <= nr < R and 0 <= nc < C):
            continue
        ch = grid[nr][nc]
        if ch == '.':
            continue
        if opposite[d] in ports.get(ch, set()):
            start_ports.append(d)

    # Problem guarantees exactly two connections for S
    # (If not, still proceed safely.)
    start_ports_set = set(start_ports)

    def can_move(r, c, d):
        dr, dc = dirs[d]
        nr, nc = r + dr, c + dc
        if not (0 <= nr < R and 0 <= nc < C):
            return False
        cur = grid[r][c]
        nxt = grid[nr][nc]
        if nxt == '.':
            return False

        cur_ports = start_ports_set if cur == 'S' else ports.get(cur, set())
        nxt_ports = ports.get(nxt, set())
        return (d in cur_ports) and (opposite[d] in nxt_ports)

    # BFS from S over valid bidirectional pipe connections
    dist = [[-1] * C for _ in range(R)]
    q = deque()
    dist[sr][sc] = 0
    q.append((sr, sc))

    while q:
        r, c = q.popleft()
        for d in range(4):
            if can_move(r, c, d):
                dr, dc = dirs[d]
                nr, nc = r + dr, c + dc
                if dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))

    ans = 0
    for r in range(R):
        for c in range(C):
            if dist[r][c] != -1:
                if dist[r][c] > ans:
                    ans = dist[r][c]

    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    solve(sys.stdin.read())

