import sys
from collections import deque

DIRS = {
    'N': (-1, 0),
    'S': (1, 0),
    'W': (0, -1),
    'E': (0, 1),
}
OPP = {'N': 'S', 'S': 'N', 'W': 'E', 'E': 'W'}

# Pipe connectivity (directions it connects to)
CONN = {
    '|': {'N', 'S'},
    '-': {'E', 'W'},
    'L': {'N', 'E'},
    'J': {'N', 'W'},
    '7': {'S', 'W'},
    'F': {'S', 'E'},
    '.': set(),
}

def solve(inp: str) -> str:
    lines = [line.rstrip('\n') for line in inp.splitlines() if line.strip('\n') != '']
    if not lines:
        return "0"
    R = len(lines)
    C = len(lines[0])
    grid = [list(row) for row in lines]

    sr = sc = -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                sr, sc = r, c
                break
        if sr != -1:
            break

    # Infer the actual pipe shape for S by checking which neighbors connect back to S
    s_dirs = []
    for d, (dr, dc) in DIRS.items():
        nr, nc = sr + dr, sc + dc
        if 0 <= nr < R and 0 <= nc < C:
            ch = grid[nr][nc]
            if ch in CONN and OPP[d] in CONN[ch]:
                s_dirs.append(d)
    s_dirs_set = set(s_dirs)

    # Determine S pipe char from its two directions
    if s_dirs_set == {'N', 'S'}:
        s_char = '|'
    elif s_dirs_set == {'E', 'W'}:
        s_char = '-'
    elif s_dirs_set == {'N', 'E'}:
        s_char = 'L'
    elif s_dirs_set == {'N', 'W'}:
        s_char = 'J'
    elif s_dirs_set == {'S', 'W'}:
        s_char = '7'
    elif s_dirs_set == {'S', 'E'}:
        s_char = 'F'
    else:
        # Should not happen for valid inputs
        s_char = '|'

    # Traverse the main loop starting from S
    # Choose one neighbor direction from S to start
    start_dirs = list(CONN[s_char])
    # Pick arbitrary first direction
    first_dir = start_dirs[0]
    pr, pc = sr, sc
    dr, dc = DIRS[first_dir]
    cr, cc = sr + dr, sc + dc

    loop_tiles = []
    in_loop = [[False] * C for _ in range(R)]
    in_loop[sr][sc] = True

    while not (cr == sr and cc == sc):
        loop_tiles.append((cr, cc))
        in_loop[cr][cc] = True
        ch = grid[cr][cc]
        if ch == 'S':
            ch = s_char
        dirs = CONN[ch]
        # Determine next direction: the one not leading back to previous cell
        # Compute direction from current to previous
        back_dir = None
        if pr == cr - 1 and pc == cc:
            back_dir = 'N'
        elif pr == cr + 1 and pc == cc:
            back_dir = 'S'
        elif pr == cr and pc == cc - 1:
            back_dir = 'W'
        elif pr == cr and pc == cc + 1:
            back_dir = 'E'
        # Next direction is the other one
        next_dir = (dirs - {back_dir}).pop()
        ndr, ndc = DIRS[next_dir]
        nr, nc = cr + ndr, cc + ndc
        pr, pc = cr, cc
        cr, cc = nr, nc

    # Expanded grid flood-fill
    ER = 2 * R + 1
    EC = 2 * C + 1
    blocked = [[False] * EC for _ in range(ER)]

    def mark_block(r, c):
        blocked[r][c] = True

    # Mark loop pipes as walls in expanded grid
    for r in range(R):
        for c in range(C):
            if not in_loop[r][c]:
                continue
            ch = grid[r][c]
            if ch == 'S':
                ch = s_char
            if ch == '.':
                continue
            cr, cc = 2 * r + 1, 2 * c + 1
            mark_block(cr, cc)  # block center to prevent leakage through pipe interior
            for d in CONN[ch]:
                dr, dc = DIRS[d]
                ar, ac = cr + dr, cc + dc  # arm cell between center and neighbor
                if 0 <= ar < ER and 0 <= ac < EC:
                    mark_block(ar, ac)

    # Flood fill from outside (0,0) in expanded grid
    visited = [[False] * EC for _ in range(ER)]
    q = deque()
    if not blocked[0][0]:
        visited[0][0] = True
        q.append((0, 0))

    while q:
        r, c = q.popleft()
        for dr, dc in DIRS.values():
            nr, nc = r + dr, c + dc
            if 0 <= nr < ER and 0 <= nc < EC and not visited[nr][nc] and not blocked[nr][nc]:
                visited[nr][nc] = True
                q.append((nr, nc))

    # Count enclosed tiles: non-loop tiles whose center is not reachable from outside
    ans = 0
    for r in range(R):
        for c in range(C):
            if in_loop[r][c]:
                continue
            cr, cc = 2 * r + 1, 2 * c + 1
            if not visited[cr][cc]:
                ans += 1

    return str(ans)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

