import sys
from functools import lru_cache

def count_arrangements(pattern: str, groups: list[int]) -> int:
    # Unfold for Part Two
    pattern2 = "?".join([pattern] * 5)
    groups2 = groups * 5
    n = len(pattern2)
    m = len(groups2)

    @lru_cache(maxsize=None)
    def dp(pos: int, gi: int, run: int) -> int:
        # pos: current index in pattern2
        # gi: number of groups already completed
        # run: current length of the ongoing contiguous '#' run (0 means not in a run)
        if run > 0 and gi >= m:
            return 0
        if run > 0 and run > groups2[gi]:
            return 0

        if pos == n:
            if run == 0:
                return 1 if gi == m else 0
            # run > 0: must finish the current group exactly at end
            return 1 if (gi < m and run == groups2[gi] and gi + 1 == m) else 0

        ch = pattern2[pos]
        total = 0

        # Try placing '.'
        if ch == '.' or ch == '?':
            if run == 0:
                total += dp(pos + 1, gi, 0)
            else:
                # End the current run; must match exactly the required group size
                if gi < m and run == groups2[gi]:
                    total += dp(pos + 1, gi + 1, 0)

        # Try placing '#'
        if ch == '#' or ch == '?':
            if gi < m:
                if run == 0:
                    # Start a new run
                    if 1 <= groups2[gi]:
                        total += dp(pos + 1, gi, 1)
                else:
                    # Extend existing run
                    if run + 1 <= groups2[gi]:
                        total += dp(pos + 1, gi, run + 1)

        return total

    return dp(0, 0, 0)

