import sys

def parse_patterns(lines):
    patterns = []
    cur = []
    for line in lines:
        line = line.rstrip("\n")
        if not line.strip():
            if cur:
                patterns.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        patterns.append(cur)
    return patterns

def mismatch_vertical(grid, c):
    # reflection line between columns c-1 and c, where c in [1..W-1]
    H = len(grid)
    W = len(grid[0])
    mismatches = 0
    for r in range(H):
        k = 0
        while True:
            L = c - 1 - k
            R = c + k
            if L < 0 or R >= W:
                break
            if grid[r][L] != grid[r][R]:
                mismatches += 1
            k += 1
    return mismatches

def mismatch_horizontal(grid, rline):
    # reflection line between rows rline-1 and rline, where rline in [1..H-1]
    H = len(grid)
    W = len(grid[0])
    mismatches = 0
    for col in range(W):
        k = 0
        while True:
            U = rline - 1 - k
            D = rline + k
            if U < 0 or D >= H:
                break
            if grid[U][col] != grid[D][col]:
                mismatches += 1
            k += 1
    return mismatches

def solve(patterns):
    total = 0
    for grid in patterns:
        H = len(grid)
        W = len(grid[0])

        old_scores = set()

        # Find all perfect reflection lines in the original pattern
        for c in range(1, W):
            if mismatch_vertical(grid, c) == 0:
                old_scores.add(c)
        for r in range(1, H):
            if mismatch_horizontal(grid, r) == 0:
                old_scores.add(100 * r)

        # Find the new reflection line after fixing exactly one smudge
        found = False
        for c in range(1, W):
            if mismatch_vertical(grid, c) == 1:
                score = c
                if score not in old_scores:
                    total += score
                    found = True
                    break
        if found:
            continue

        for r in range(1, H):
            if mismatch_horizontal(grid, r) == 1:
                score = 100 * r
                if score not in old_scores:
                    total += score
                    found = True
                    break

        # Problem guarantees a solution
        if not found:
            # Fallback (should not happen with valid inputs)
            pass

    return total

def main():
    lines = sys.stdin.read().splitlines()
    patterns = parse_patterns(lines)
    ans = solve(patterns)
    print(ans)

if __name__ == "__main__":
    main()

