import sys
from fractions import Fraction

def solve():
    stones = []
    for line in sys.stdin.read().splitlines():
        line = line.strip()
        if not line:
            continue
        left, right = line.split('@')
        px, py, pz = map(int, left.strip().split(','))
        vx, vy, vz = map(int, right.strip().split(','))
        stones.append((px, py, pz, vx, vy, vz))

    n = len(stones)
    if n < 2:
        print(0)
        return

    # Decide test area (sample vs real input)
    max_abs = 0
    for px, py, pz, vx, vy, vz in stones:
        max_abs = max(max_abs, abs(px), abs(py), abs(pz), abs(vx), abs(vy), abs(vz))

    if max_abs <= 50:
        minX, maxX = 7, 27
        minY, maxY = 7, 27
    else:
        minX, maxX = 200000000000000, 400000000000000
        minY, maxY = 200000000000000, 400000000000000

    minXf, maxXf = Fraction(minX), Fraction(maxX)
    minYf, maxYf = Fraction(minY), Fraction(maxY)

    ans = 0

    for i in range(n):
        xi, yi, _, vxi, vyi, _ = stones[i]
        for j in range(i + 1, n):
            xj, yj, _, vxj, vyj, _ = stones[j]

            dx = xj - xi
            dy = yj - yi
            dvx = vxi - vxj
            dvy = vyi - vyj

            # If both relative velocities are zero in x and y
            if dvx == 0 and dvy == 0:
                # Same position in x and y => coincide forever (not a single intersection event)
                if dx == 0 and dy == 0:
                    continue
                # Otherwise never meet
                continue

            t = None

            # X axis constraint
            if dvx == 0:
                if dx != 0:
                    continue  # never meet in x
            else:
                t = Fraction(dx, dvx)

            # Y axis constraint
            if dvy == 0:
                if dy != 0:
                    continue  # never meet in y
            else:
                tY = Fraction(dy, dvy)
                if t is None:
                    t = tY
                else:
                    if t != tY:
                        continue

            # Future only
            if t < 0:
                continue

            x_int = Fraction(xi) + Fraction(vxi) * t
            y_int = Fraction(yi) + Fraction(vyi) * t

            if minXf <= x_int <= maxXf and minYf <= y_int <= maxYf:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

