            dvx = vxi - vxj
            dvy = vyi - vyj

            # If both relative velocities are zero in x and y
            if dvx == 0 and dvy == 0:
                # Same position in x and y => coincide forever (not a single intersection event)
                if dx == 0 and dy == 0:
                    continue
                # Otherwise never meet
                continue

            t = None

            # X axis constraint
            if dvx == 0:
                if dx != 0:
                    continue  # never meet in x
            else:
                t = Fraction(dx, dvx)

            # Y axis constraint
            if dvy == 0:
                if dy != 0:
                    continue  # never meet in y
            else:
                tY = Fraction(dy, dvy)
                if t is None:
                    t = tY
                else:
                    if t != tY:
                        continue

            # Future only
            if t < 0:
                continue

            x_int = Fraction(xi) + Fraction(vxi) * t
            y_int = Fraction(yi) + Fraction(vyi) * t

            if minXf <= x_int <= maxXf and minYf <= y_int <= maxYf:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

