import sys

def count_safe_reports(lines):
    safe_count = 0

    for line in lines:
        line = line.strip()
        if not line:
            continue

        levels = list(map(int, line.split()))
        n = len(levels)

        if n <= 1:
            safe_count += 1
            continue

        # Determine required direction (increasing or decreasing)
        direction = 0  # +1 for increasing, -1 for decreasing
        unsafe = False

        for i in range(n - 1):
            delta = levels[i + 1] - levels[i]
            if delta == 0:
                unsafe = True
                break
            if direction == 0:
                direction = 1 if delta > 0 else -1

        if unsafe:
            continue

        # Validate entire report
        for i in range(n - 1):
            delta = levels[i + 1] - levels[i]
            ad = abs(delta)
            if ad < 1 or ad > 3:
                unsafe = True
                break
            if direction == 1 and delta <= 0:
                unsafe = True
                break
            if direction == -1 and delta >= 0:
                unsafe = True
                break

        if not unsafe:
            safe_count += 1

    return safe_count

def main():
    lines = sys.stdin.read().splitlines()
    result = count_safe_reports(lines)
    print(result)

if __name__ == "__main__":
    main()

