import sys
from collections import deque

def solve():
    raw = sys.stdin.read().splitlines()
    if not raw:
        return

    R = len(raw)
    C = max(len(line) for line in raw)

    # Pad shorter lines with walls to keep a rectangular grid
    grid = []
    S = E = None
    for r in range(R):
        line = raw[r]
        if len(line) < C:
            line = line + "#" * (C - len(line))
        grid.append(line)
        for c, ch in enumerate(line):
            if ch == 'S':
                S = (r, c)
            elif ch == 'E':
                E = (r, c)

    if S is None or E is None:
        print(0)
        return

    passable = [[grid[r][c] != '#' for c in range(C)] for r in range(R)]
    INF = 10**18
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def inb(r, c):
        return 0 <= r < R and 0 <= c < C

    def bfs_from(src):
        dist = [[INF] * C for _ in range(R)]
        q = deque([src])
        sr, sc = src
        dist[sr][sc] = 0
        while q:
            r, c = q.popleft()
            nd = dist[r][c] + 1
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if inb(nr, nc) and passable[nr][nc] and nd < dist[nr][nc]:
                    dist[nr][nc] = nd
                    q.append((nr, nc))
        return dist

    distS = bfs_from(S)
    distE = bfs_from(E)

    normal = distS[E[0]][E[1]]
    if normal >= INF:
        print(0)
        return

    ans = 0

    # Enumerate cheat start a and cheat end b reachable in exactly 2 moves.
    # Intermediate cell may be a wall (collision disabled), but b must be normal track.
    for ar in range(R):
        for ac in range(C):
            if distS[ar][ac] >= INF:
                continue

            for dr1, dc1 in dirs:
                r1, c1 = ar + dr1, ac + dc1
                if not inb(r1, c1):
                    continue

                for dr2, dc2 in dirs:
                    br, bc = r1 + dr2, c1 + dc2
                    if not inb(br, bc):
                        continue

                    if not passable[br][bc]:
                        continue
                    if distE[br][bc] >= INF:
                        continue

                    total = distS[ar][ac] + 2 + distE[br][bc]
                    if normal - total >= 100:
                        ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

