import sys
from collections import deque

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    grid = [list(line.rstrip("\n")) for line in lines]
    R = len(grid)
    row_len = [len(row) for row in grid]

    sr = sc = er = ec = None

    def is_track(r, c):
        ch = grid[r][c]
        return ch == '.' or ch == 'S' or ch == 'E'

    for r in range(R):
        for c in range(row_len[r]):
            if grid[r][c] == 'S':
                sr, sc = r, c
            elif grid[r][c] == 'E':
                er, ec = r, c

    def bfs_normal(start_r, start_c):
        dist = [[-1] * row_len[r] for r in range(R)]
        q = deque([(start_r, start_c)])
        dist[start_r][start_c] = 0
        while q:
            r, c = q.popleft()
            nd = dist[r][c] + 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < row_len[nr] and dist[nr][nc] == -1 and is_track(nr, nc):
                    dist[nr][nc] = nd
                    q.append((nr, nc))
        return dist

    distS = bfs_normal(sr, sc)
    distE = bfs_normal(er, ec)

    base = distS[er][ec]
    if base == -1:
        print(0)
        return

    MAX_CHEAT = 20
    ans = 0

    # Enumerate cheat start a (must be track and reachable from S)
    for a_r in range(R):
        for a_c in range(row_len[a_r]):
            if not is_track(a_r, a_c):
                continue
            da = distS[a_r][a_c]
            if da == -1:
                continue

            # BFS for cheat segment: can move through any cells for up to 20 steps
            distCheat = [[-1] * row_len[r] for r in range(R)]
            q = deque([(a_r, a_c)])
            distCheat[a_r][a_c] = 0

            while q:
                r, c = q.popleft()
                d = distCheat[r][c]

                # Cheat ends must be on normal track and reachable to E
                if is_track(r, c):
                    de = distE[r][c]
                    if de != -1:
                        total = da + d + de
                        if base - total >= 100:
                            ans += 1

                if d == MAX_CHEAT:
                    continue

                nd = d + 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < row_len[nr] and distCheat[nr][nc] == -1:
                        distCheat[nr][nc] = nd
                        q.append((nr, nc))

    print(ans)

if __name__ == "__main__":
    solve()

