import sys
from collections import deque, defaultdict
from functools import lru_cache

DIR_LAYOUT = [
    " ^A",
    "<v>",
]
NUM_LAYOUT = [
    "789",
    "456",
    "123",
    " 0A",
]

def build_graph(layout):
    R = len(layout)
    C = len(layout[0])
    key_to_pos = {}
    pos_to_key = {}
    for r in range(R):
        for c in range(C):
            ch = layout[r][c]
            if ch != ' ':
                pos_to_key[(r, c)] = ch
                key_to_pos[ch] = (r, c)

    move_letter = {(-1, 0): '^', (1, 0): 'v', (0, -1): '<', (0, 1): '>'}
    adj = {k: [] for k in key_to_pos}
    for k, (r, c) in key_to_pos.items():
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) in pos_to_key:
                nk = pos_to_key[(nr, nc)]
                adj[k].append((nk, move_letter[(dr, dc)]))
    return key_to_pos, adj

def all_shortest_move_strings(key_to_pos, adj):
    nodes = list(key_to_pos.keys())

    # BFS distances from each source
    dist_all = {}
    for s in nodes:
        dist = {v: 10**9 for v in nodes}
        dist[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for nv, _mv in adj[v]:
                if dist[nv] > dist[v] + 1:
                    dist[nv] = dist[v] + 1
                    q.append(nv)
        dist_all[s] = dist

    # Enumerate all shortest move strings for each (s,t)
    shortest = {}
    for s in nodes:
        dist = dist_all[s]
        dag = defaultdict(list)
        for v in nodes:
            for nv, mv in adj[v]:
                if dist[nv] == dist[v] + 1:
                    dag[v].append((nv, mv))

        for t in nodes:
            if dist[t] >= 10**8:
                shortest[(s, t)] = []
                continue

            res = []
            path = []

            def dfs(v):
                if v == t:
                    res.append(''.join(path))
                    return
                for nv, mv in dag[v]:
                    path.append(mv)
                    dfs(nv)
                    path.pop()

            dfs(s)
            shortest[(s, t)] = res
    return shortest

dir_pos, dir_adj = build_graph(DIR_LAYOUT)
num_pos, num_adj = build_graph(NUM_LAYOUT)

DIR_MOVES = all_shortest_move_strings(dir_pos, dir_adj)  # between directional keys
NUM_MOVES = all_shortest_move_strings(num_pos, num_adj)  # between numeric keys

# dp(level, a, b):
# level in {0,1,2} for directional keypads:
#   0 = lowest directional keypad (directly controls numeric keypad)
#   1 = middle directional keypad (controlled by level 2)
#   2 = topmost directional keypad (you type on this)
#
# Returns minimal number of button presses on the topmost keypad (level 2)
# needed to make the keypad at 'level' press key 'b' after starting at 'a'.
@lru_cache(None)
def dp(level, a, b):
    moves = DIR_MOVES[(a, b)]  # strings over '^v<>', shortest to move arm from a to b
    if level == 0:
        # On the lowest directional keypad, we can directly press the required keys:
        # move string length + 1 for pressing 'A' to activate b.
        return min(len(m) + 1 for m in moves)

    best = 10**18
    for m in moves:
        # To make level 'level' press b, the keypad at level-1 must type:
        #   (move string) then 'A' to activate b on level.
        seq = m + 'A'
        cur = 'A'
        total = 0
        for ch in seq:
            total += dp(level - 1, cur, ch)
            cur = ch
        best = min(best, total)
    return best

def numeric_transition_cost(d1, d2):
    """
    Cost on the topmost keypad to make the numeric keypad press d2,
    given that the numeric keypad arm starts at d1.
    The numeric keypad is controlled by the lowest directional keypad (level 0),
    which is controlled recursively up to level 2.
    """
    moves = NUM_MOVES[(d1, d2)]  # strings over '^v<>', shortest to move arm on numeric keypad
    best = 10**18
    for m in moves:
        # Lowest directional keypad must type (m + 'A') to press d2 on numeric keypad.
        # That typing is done by level 1 keypad, so we call dp(1, ...)
        seq = m + 'A'
        cur = 'A'
        total = 0
        for ch in seq:
            total += dp(1, cur, ch)
            cur = ch
        best = min(best, total)
    return best

