import sys
from collections import defaultdict

def solve(data: str) -> str:
    adj = defaultdict(list)
    nodes = set()

    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        if ":" not in line:
            continue
        left, right = line.split(":", 1)
        u = left.strip()
        nodes.add(u)
        outs = right.strip().split()
        for v in outs:
            if v:
                adj[u].append(v)
                nodes.add(v)

    start = "svr"
    end = "out"
    A = "dac"
    B = "fft"

    # Ensure all nodes exist in adjacency dict
    for n in nodes:
        adj.setdefault(n, [])

    # DP: number of paths from u to end
    memo_to_end = {}
    visiting = set()

    def count_to_end(u: str) -> int:
        if u == end:
            return 1
        if u in memo_to_end:
            return memo_to_end[u]
        if u in visiting:
            # Should not happen for valid inputs (DAG). Avoid infinite recursion.
            return 0
        visiting.add(u)
        total = 0
        for v in adj[u]:
            total += count_to_end(v)
        visiting.remove(u)
        memo_to_end[u] = total
        return total

    # DP: number of paths from start to u (use reverse edges)
    radj = defaultdict(list)
    for u, outs in adj.items():
        for v in outs:
            radj[v].append(u)

    memo_from_start = {}

    def count_from_start(u: str) -> int:
        if u == start:
            return 1
        if u in memo_from_start:
            return memo_from_start[u]
        total = 0
        for p in radj.get(u, []):
            total += count_from_start(p)
        memo_from_start[u] = total
        return total

    # DP: number of paths from u to target (generalized)
    def count_to_target(target: str) -> int:
        memo = {}
        visiting_local = set()

        def dfs(u: str) -> int:
            if u == target:
                return 1
            if u in memo:
                return memo[u]
            if u in visiting_local:
                return 0
            visiting_local.add(u)
            total = 0
            for v in adj[u]:
                total += dfs(v)
            visiting_local.remove(u)
            memo[u] = total
            return total

        return dfs

    dfs_to_B = count_to_target(B)
    dfs_to_A = count_to_target(A)

    waysToOut_A = count_to_end(A)
    waysToOut_B = count_to_end(B)

    waysFromStart_A = count_from_start(A)
    waysFromStart_B = count_from_start(B)

    waysAtoB = dfs_to_B(A)
    waysBtoA = dfs_to_A(B)

    ans = waysFromStart_A * waysAtoB * waysToOut_B + waysFromStart_B * waysBtoA * waysToOut_A
    return str(ans)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

