import sys
from functools import lru_cache

def parse_input(data: str):
    lines = [ln.rstrip("\n") for ln in data.splitlines()]

    def is_shape_header(s: str):
        s = s.strip()
        if not s.endswith(":"):
            return False
        left = s[:-1].strip()
        return left.isdigit()

    def is_region_header(s: str):
        s = s.strip()
        if not s.endswith(":"):
            return False
        left = s[:-1].strip()
        if "x" not in left:
            return False
        w, h = left.split("x", 1)
        return w.isdigit() and h.isdigit()

