import sys
import math

def parse_program(lines):
    prog = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        x = parts[1]
        y = parts[2] if len(parts) > 2 else None
        prog.append((op, x, y))
    return prog

def run_part1(prog):
    regs = {}
    def val(operand):
        if operand is None:
            return 0
        if operand.lstrip("-").isdigit():
            return int(operand)
        return regs.get(operand, 0)

    ip = 0
    mul_count = 0
    n = len(prog)
    while 0 <= ip < n:
        op, X, Y = prog[ip]
        if op == "set":
            regs[X] = val(Y)
            ip += 1
        elif op == "sub":
            regs[X] = regs.get(X, 0) - val(Y)
            ip += 1
        elif op == "mul":
            regs[X] = regs.get(X, 0) * val(Y)
            mul_count += 1
            ip += 1
        elif op == "jnz":
            if val(X) != 0:
                ip += val(Y)
            else:
                ip += 1
        else:
            raise ValueError(f"Unknown op: {op}")
    return mul_count

def run_until_divisor_constant(prog, a_value=1):
    # Execute until we can infer the constant N used in the divisor loop.
    # For this known AoC program, N ends up in register 'g' (commonly) or 'f'/'e' depending on variant.
    # We'll detect by watching for the point where the nested loops begin:
    # Typically, the code sets up b and c and then checks b*c == N.
    # We'll run and stop when we first see a 'mul' that multiplies two loop variables and then a 'jnz' based on equality.
    regs = {}
    regs["a"] = a_value

    def val(operand):
        if operand is None:
            return 0
        if operand.lstrip("-").isdigit():
            return int(operand)
        return regs.get(operand, 0)

    ip = 0
    n = len(prog)

    # Heuristic: find the first time we reach a state where:
    # - registers b and c are initialized (often via set)
    # - and there is a multiplication of b and c (mul b c) or similar
    # We'll stop right after the constant N is computed into some register by tracking assignments
    # to candidate registers right before the divisor loop.
    # Candidate registers are those that are later used in comparisons with b*c.
    # We'll just run until we encounter a 'mul' where both operands are registers and one of them is 'b' or 'c'.
    # Then we look backward for the register used in the subsequent equality check.
    #
    # More robust: run until we see a pattern:
    #   mul X Y
    #   sub Z W
    #   jnz ...
    # But easiest: run until we see a 'mul' instruction where operands are loop vars (b and c),
    # then the constant N is the other operand in the equality check that follows.
    #
    # We'll implement a small lookahead: when we hit mul, inspect next few instructions to find
    # a 'jnz' that depends on a register that was set to (b*c - N) or (N - b*c).
    # Then N is the value of the register used in that subtraction at that moment.
    #
    # Since this is a known puzzle, this heuristic works well.

    while 0 <= ip < n:
        op, X, Y = prog[ip]

        if op == "set":
            regs[X] = val(Y)
            ip += 1
        elif op == "sub":
            regs[X] = regs.get(X, 0) - val(Y)
            ip += 1
        elif op == "mul":
            # Detect divisor loop multiplication
            # Commonly: mul e b ; or mul f b ; but operands include b and c.
            if (X in ("b", "c") or Y in ("b", "c")) or (X in regs and Y in regs and (X == "b" or X == "c" or Y == "b" or Y == "c")):
                # Execute mul
                regs[X] = regs.get(X, 0) * val(Y)
                # Look ahead for subtraction with a constant N
                # Search next up to 6 instructions for "sub <tmp> <constRegOrLiteral>" where <tmp> is X or derived from it.
                # Then N is the value of that constant operand at that time.
                for k in range(1, 7):
                    if ip + k >= n:
                        break
                    op2, X2, Y2 = prog[ip + k]
                    if op2 == "sub":
                        # If subtraction uses the mul result register as target, then Y2 is N (or vice versa)
                        if X2 == X:
                            # tmp = tmp - Y2 => tmp becomes b*c - N, so N is val(Y2)
                            return val(Y2)
                        # If subtraction uses a register that was set from mul result, we can't be sure; still try:
                        if X2 in regs and X2 == X:
                            return val(Y2)
                # If heuristic didn't find, continue
                ip += 1
            else:
                regs[X] = regs.get(X, 0) * val(Y)
                ip += 1
        elif op == "jnz":
            if val(X) != 0:
                ip += val(Y)
            else:
                ip += 1
        else:
            raise ValueError(f"Unknown op: {op}")

    raise RuntimeError("Failed to determine divisor constant N")

def divisor_count(N):
    # Count number of divisors of N
    r = math.isqrt(N)
    cnt = 0
    for d in range(1, r + 1):
        if N % d == 0:
            cnt += 1
            other = N // d
            if other != d:
                cnt += 1
    return cnt

def main():
    lines = sys.stdin.read().splitlines()
    prog = parse_program(lines)

    part1 = run_part1(prog)

    # Part 2: set a=1 and compute h.
    # For this puzzle variant, h counts number of divisors of N.
    N = run_until_divisor_constant(prog, a_value=1)
    part2 = divisor_count(N)

    sys.stdout.write(f"{part1}\n{part2}\n")

if __name__ == "__main__":
    main()

