    #
    # We'll implement a small lookahead: when we hit mul, inspect next few instructions to find
    # a 'jnz' that depends on a register that was set to (b*c - N) or (N - b*c).
    # Then N is the value of the register used in that subtraction at that moment.
    #
    # Since this is a known puzzle, this heuristic works well.

    while 0 <= ip < n:
        op, X, Y = prog[ip]

        if op == "set":
            regs[X] = val(Y)
            ip += 1
        elif op == "sub":
            regs[X] = regs.get(X, 0) - val(Y)
            ip += 1
        elif op == "mul":
            # Detect divisor loop multiplication
            # Commonly: mul e b ; or mul f b ; but operands include b and c.
            if (X in ("b", "c") or Y in ("b", "c")) or (X in regs and Y in regs and (X == "b" or X == "c" or Y == "b" or Y == "c")):
                # Execute mul
                regs[X] = regs.get(X, 0) * val(Y)
                # Look ahead for subtraction with a constant N
                # Search next up to 6 instructions for "sub <tmp> <constRegOrLiteral>" where <tmp> is X or derived from it.
                # Then N is the value of that constant operand at that time.
                for k in range(1, 7):
                    if ip + k >= n:
                        break
                    op2, X2, Y2 = prog[ip + k]
                    if op2 == "sub":
                        # If subtraction uses the mul result register as target, then Y2 is N (or vice versa)
                        if X2 == X:
                            # tmp = tmp - Y2 => tmp becomes b*c - N, so N is val(Y2)
                            return val(Y2)
                        # If subtraction uses a register that was set from mul result, we can't be sure; still try:
                        if X2 in regs and X2 == X:
                            return val(Y2)
                # If heuristic didn't find, continue
                ip += 1
            else:
                regs[X] = regs.get(X, 0) * val(Y)
                ip += 1
        elif op == "jnz":
            if val(X) != 0:
                ip += val(Y)
            else:
                ip += 1
        else:
            raise ValueError(f"Unknown op: {op}")

    raise RuntimeError("Failed to determine divisor constant N")

def divisor_count(N):
    # Count number of divisors of N
    r = math.isqrt(N)
    cnt = 0
    for d in range(1, r + 1):
        if N % d == 0:
            cnt += 1
            other = N // d
            if other != d:
                cnt += 1
    return cnt

def main():
    lines = sys.stdin.read().splitlines()
    prog = parse_program(lines)

    part1 = run_part1(prog)

    # Part 2: set a=1 and compute h.
    # For this puzzle variant, h counts number of divisors of N.
    N = run_until_divisor_constant(prog, a_value=1)
    part2 = divisor_count(N)

    sys.stdout.write(f"{part1}\n{part2}\n")

if __name__ == "__main__":
    main()

