import sys

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    if not lines:
        return "0"
    R, C = len(lines), len(lines[0])
    grid = [list(row) for row in lines]

    dir_map = {'^': 0, '>': 1, 'v': 2, '<': 3}  # Up, Right, Down, Left
    dr = [-1, 0, 1, 0]
    dc = [0, 1, 0, -1]

    sr = sc = sdir = None
    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch in dir_map:
                sr, sc, sdir = r, c, dir_map[ch]
                grid[r][c] = '.'  # treat as empty for movement
                break
        if sr is not None:
            break

    is_wall = [[grid[r][c] == '#' for c in range(C)] for r in range(R)]

    def step(r, c, d, extra_block=None):
        nr, nc = r + dr[d], c + dc[d]
        if nr < 0 or nr >= R or nc < 0 or nc >= C:
            return None  # leaves grid
        if is_wall[nr][nc] or (extra_block is not None and nr == extra_block[0] and nc == extra_block[1]):
            return (r, c, (d + 1) % 4)  # turn right, stay in place
        return (nr, nc, d)  # move forward

    # Part 1: simulate original path to collect candidate cells
    visited_cells = set()
    r, c, d = sr, sc, sdir
    visited_cells.add((r, c))
    while True:
        nxt = step(r, c, d, extra_block=None)
        if nxt is None:
            break
        r, c, d = nxt
        visited_cells.add((r, c))

    # Part 2: for each candidate cell (except start), test if it causes a loop
    ans = 0
    for br, bc in visited_cells:
        if br == sr and bc == sc:
            continue

        seen = [[[False] * 4 for _ in range(C)] for __ in range(R)]
        r, c, d = sr, sc, sdir
        while True:
            if seen[r][c][d]:
                ans += 1
                break
            seen[r][c][d] = True

            nxt = step(r, c, d, extra_block=(br, bc))
            if nxt is None:
                break
            r, c, d = nxt

    return str(ans)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

