import sys

def can_make_target(target: int, nums: list[int]) -> bool:
    if not nums:
        return False
    if len(nums) == 1:
        return nums[0] == target

    reachable = {nums[0]}
    for x in nums[1:]:
        next_reachable = set()
        for v in reachable:
            a = v + x
            if a <= target:
                next_reachable.add(a)
            m = v * x
            if m <= target:
                next_reachable.add(m)
        if not next_reachable:
            return False
        if target in next_reachable:
            return True
        reachable = next_reachable

    return target in reachable

def solve() -> None:
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        left, right = line.split(":")
        target = int(left.strip())
        nums = list(map(int, right.strip().split()))
        if can_make_target(target, nums):
            total += target
    print(total)

if __name__ == "__main__":
    solve()

